{
  "specialty": "kdoctor-rheumatology",
  "answer": "임신 8주·BP 146/94·단백뇨 2+·부종은 루푸스 신염 재활성과 APS/TMA(비정상 임신 관련 신장병증 포함) 중 어느 쪽으로도 설명 가능하며, 임신 관련 고혈압·전자간증 전구 상태도 겹칠 수 있습니다. 원인 감별과 임신 안전성을 동시에 평가해야 하므로 24~48시간 내 산과·신장·류마티스 대면 평가가 필요합니다. 면역억제 조정은 자기 판단으로 결정할 문제가 아니며, 반드시 처방 의료진(류마티스+산과)이 검사 결과를 보고 결정해야 합니다.",
  "red_flag": {
    "present": true,
    "items": [
      { "id": "RH5", "evidence": "SLE 활성 + 단백뇨·부종 (신장 침범 시사)", "basis": "history" },
      { "id": "임신 관련 고혈압/전자간증", "evidence": "임신 8주, BP 146/94, 단백뇨 2+, 부종", "basis": "measurement" },
      { "id": "APS + 유산 2회", "evidence": "혈전/태반 혈관 병증 위험", "basis": "history" }
    ]
  },
  "hypotheses": [
    {
      "name": "루푸스 신염 재활성(특히 증식성)",
      "icd10": "M32.14 / N08.5",
      "must_not_miss": true,
      "probability_band": "high",
      "supports": [
        { "text": "SLE 4년 병력, HCQ+PDN 5mg 유지 중", "basis": "history" },
        { "text": "단백뇨 2+, 부종, 고혈압", "basis": "measurement" }
      ],
      "against": [
        { "text": "현재 PDN 5mg로 안정 유지 중이었다면 급격한 재활성은 상대적으로 낮을 수 있음", "basis": "history" }
      ]
    },
    {
      "name": "APS 관련 신장병증 / 혈전성 미세혈관병증(TMA)",
      "icd10": "D68.61 / M31.1",
